-- Gallery images belonging to a project

create table "public"."project_images" (
  "id" bigint primary key generated by default as identity,
  "image" varchar,
  "project_id" bigint,
  "order" integer,
  "is_active" boolean not null default true
);

alter table "public"."project_images" add constraint "project_images_project_fkey" foreign key ("project_id") references "public"."projects" (id) on update cascade on delete cascade;

alter table "public"."project_images" enable row level security;
create policy "Enable read access for all users" on "public"."project_images" for select using (true);

grant all on "public"."project_images" to postgres, anon, authenticated, service_role;
